// قاعدة البيانات الموحدة (الأصلية + الإضافية)
const UNIFIED_DTC_DATABASE: Record<string, MegaDTCEntry> = {
  ...MEGA_DTC_DATABASE,
  ...ADDITIONAL_DTC_DATABASE,
};

export function lookupMegaDTC(code: string): MegaDTCEntry | undefined {
  const upper = code.toUpperCase().trim();
  if (UNIFIED_DTC_DATABASE[upper]) return UNIFIED_DTC_DATABASE[upper];
  const base = upper.split('-')[0];
  return UNIFIED_DTC_DATABASE[base];
}

export function getMegaDTCCount(): number {
  return Object.keys(UNIFIED_DTC_DATABASE).length;
}

export function searchDTCs(query: string): MegaDTCEntry[] {
  const q = query.toUpperCase().trim();
  if (!q) return [];
  const results: MegaDTCEntry[] = [];
  for (const [code, entry] of Object.entries(UNIFIED_DTC_DATABASE)) {
    if (code.includes(q) || entry.description.includes(query)) {
      results.push(entry);
    }
    if (results.length >= 50) break;
  }
  return results;
}
